let toastTimer;
const dialogReturnFocus=new WeakMap();
const reducedSystem = matchMedia('(prefers-reduced-motion: reduce)');
let reducedUser = store.get('tigo-reduced-motion',false)===true;
const reduced = ()=>reducedSystem.matches||reducedUser;
function updateMotion(){document.documentElement.classList.toggle('motion-off',reduced());$('#motionToggle').setAttribute('aria-pressed',String(reduced()));$('#motionToggle').setAttribute('aria-label',reduced()?'Animasi dikurangi, klik untuk mengubah preferensi':'Kurangi animasi');$('#motionToggle').title=reduced()?'Animasi dikurangi':'Kurangi animasi';if(reduced())$$('.reveal').forEach(el=>{el.classList.remove('pending');el.classList.add('in-view');});}
$('#motionToggle').addEventListener('click',()=>{reducedUser=!reducedUser;store.set('tigo-reduced-motion',reducedUser);updateMotion();notify(reducedSystem.matches?'Mengikuti pengaturan pengurangan gerak perangkat.':reducedUser?'Animasi dikurangi.':'Animasi diaktifkan.');});
reducedSystem.addEventListener('change',updateMotion);updateMotion();
function notify(text){const el=$('#toast');clearTimeout(toastTimer);el.textContent=text;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),2800);}
function persistCart(){store.set('tigo-demo-cart-v1',cart);updateBadge();}
function updateBadge(){const count=cart.reduce((s,i)=>s+i.qty,0);$('#cartCount').textContent=count;$('#cartOpen').setAttribute('aria-label',`Buka keranjang, ${count} barang`);}
function subtotal(items=cart){return items.reduce((s,i)=>s+byId(i.id).price*i.qty,0);}
function openDialog(id){const dialog=$('#'+id);dialogReturnFocus.set(dialog,document.activeElement);dialog.showModal();document.body.style.overflow='hidden';}
function closeDialog(id){const dialog=$('#'+id);dialog.close();}
$$('dialog').forEach(dialog=>{dialog.addEventListener('close',()=>{const opened=$$('dialog[open]'),target=dialogReturnFocus.get(dialog);if(!opened.length)document.body.style.overflow='';if(target?.isConnected&&!target.closest('dialog:not([open])')&&(!opened.length||opened.at(-1).contains(target)))target.focus({preventScroll:true});else if(!opened.length)$('#cartOpen').focus({preventScroll:true});});dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();});});
document.addEventListener('click',event=>{const button=event.target.closest('[data-close]');if(button)closeDialog(button.dataset.close);const play=event.target.closest('[data-play-demo]');if(play)openProductDemo(play.dataset.playDemo);});
$('#menuToggle').addEventListener('click',()=>{const open=$('#menuToggle').getAttribute('aria-expanded')==='true';$('#menuToggle').setAttribute('aria-expanded',String(!open));$('#menuToggle').setAttribute('aria-label',open?'Buka menu':'Tutup menu');$('#mobileMenu').hidden=open;});
$$('#mobileMenu a').forEach(a=>a.addEventListener('click',()=>{$('#mobileMenu').hidden=true;$('#menuToggle').setAttribute('aria-expanded','false');$('#menuToggle').setAttribute('aria-label','Buka menu');}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#mobileMenu').hidden){$('#mobileMenu').hidden=true;$('#menuToggle').setAttribute('aria-expanded','false');$('#menuToggle').focus();}});

const eye='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12"/><circle cx="12" cy="12" r="3"/></svg>';
function renderProducts(){let visible=products.filter(p=>(filter==='all'||p.category===filter)&&(!query||`${p.name} ${p.short} ${p.label}`.toLocaleLowerCase('id').includes(query)));if(sort==='name')visible.sort((a,b)=>a.name.localeCompare(b.name));if(sort==='price-asc')visible.sort((a,b)=>a.price-b.price);if(sort==='price-desc')visible.sort((a,b)=>b.price-a.price);$('#productGrid').innerHTML=visible.map(p=>`<article class="product-card" data-id="${p.id}"><div class="product-photo" style="--card-bg:${p.bg}"><span class="product-index">${p.id.slice(1)}</span><span class="view-icon">${eye}</span><button class="product-image-button" data-detail="${p.id}" aria-label="Lihat detail ${p.name}"><img src="assets/${p.image}.webp" alt="${p.name}, referensi produk Montessori TIGO LAB" width="1000" height="1000" loading="lazy"></button></div><div class="product-info"><div class="product-category">${p.label}</div><h3><button class="product-name" data-detail="${p.id}">${p.name}</button></h3><p class="product-description">${p.short}</p><button class="card-demo-button" data-play-demo="${p.id}" aria-label="Lihat cara bermain ${p.name}" aria-haspopup="dialog" aria-controls="animationDialog"><span aria-hidden="true">▶</span> Cara bermain</button><div class="product-bottom"><div class="product-price">${rupiah(p.price)}<span class="example-note">harga contoh / paket</span></div><button class="add-button" data-add="${p.id}" aria-label="Tambah ${p.name} ke keranjang">+</button></div></div></article>`).join('');$('#resultCount').textContent=`Menampilkan ${visible.length} produk`;$('#emptySearch').hidden=visible.length>0;}
$$('[data-filter]').forEach(button=>button.addEventListener('click',()=>{filter=button.dataset.filter;$$('[data-filter]').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});renderProducts();}));
$('#productSearch').addEventListener('input',e=>{query=e.target.value.trim().replace(/\s+/g,' ').toLocaleLowerCase('id');renderProducts();});
$('#productSort').addEventListener('change',e=>{sort=e.target.value;renderProducts();});
$('#resetSearch').addEventListener('click',()=>{query='';filter='all';sort='featured';$('#productSearch').value='';$('#productSort').value='featured';$$('[data-filter]').forEach(b=>{const active=b.dataset.filter==='all';b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});renderProducts();$('#productSearch').focus();});
$('#productGrid').addEventListener('click',e=>{const detail=e.target.closest('[data-detail]'),add=e.target.closest('[data-add]');if(detail)showProduct(detail.dataset.detail);if(add)addToCart(add.dataset.add,1,add);});
function showProduct(id){const p=byId(id);detailId=id;detailQty=1;$('#productDetail').innerHTML=`<div class="detail-layout"><div class="detail-image" style="--detail-bg:${p.bg}"><img src="assets/${p.image}.webp" alt="${p.name}, gambar referensi dari katalog TIGO LAB" width="1000" height="1000"></div><div class="detail-copy"><div class="eyebrow">MONTESSORI / ${p.label}</div><h2 id="detailTitle">${p.name}</h2><p class="detail-description">${p.description}</p><button class="text-link detail-demo-button" data-play-demo="${p.id}" aria-haspopup="dialog" aria-controls="animationDialog"><span aria-hidden="true">▶</span> Lihat animasi cara bermain</button><div class="detail-price">${rupiah(p.price)}<span>Harga contoh per paket · belum harga jual final</span></div><div class="detail-meta"><div><span>Kode produk</span><strong>${p.id}</strong></div><div><span>Bahan & kelengkapan</span><strong>Menunggu konfirmasi</strong></div><div><span>Pemesanan</span><strong>Simulasi katalog</strong></div></div><div class="detail-package"><strong>Gambaran pada foto</strong>${p.visual}<br>Jumlah dan isi paket final dikonfirmasi sebelum penjualan.</div><div class="detail-actions"><div class="qty-control" aria-label="Jumlah produk"><button type="button" data-detail-qty="-1" aria-label="Kurangi jumlah">−</button><output id="detailQty" aria-live="polite">1</output><button type="button" data-detail-qty="1" aria-label="Tambah jumlah">+</button></div><button class="button button-blue" id="detailAdd">Tambah ke keranjang <span aria-hidden="true">+</span></button></div></div></div>`;openDialog('productDialog');}
$('#productDetail').addEventListener('click',e=>{const qty=e.target.closest('[data-detail-qty]');if(qty){detailQty=Math.max(1,Math.min(99,detailQty+Number(qty.dataset.detailQty)));$('#detailQty').textContent=detailQty;}if(e.target.closest('#detailAdd')){addToCart(detailId,detailQty,e.target.closest('#detailAdd'));const button=$('#detailAdd');button.textContent='Ditambahkan ✓';setTimeout(()=>{if(button.isConnected)button.innerHTML='Tambah ke keranjang <span aria-hidden="true">+</span>';},1200);}});
function flyToCart(p,from){if(reduced()||document.querySelector('dialog[open]')||!from)return;const source=from.closest('.product-card')?.querySelector('img')||from;const a=source.getBoundingClientRect(),b=$('#cartOpen').getBoundingClientRect();if(b.bottom<0||a.top>innerHeight)return;const image=document.createElement('img');image.className='fly-image';image.src=`assets/${p.image}.webp`;image.alt='';image.style.left=`${a.left+a.width/2-29}px`;image.style.top=`${Math.min(a.top+a.height/2,innerHeight-70)}px`;document.body.append(image);const dx=b.left+b.width/2-(a.left+a.width/2),dy=b.top+b.height/2-Math.min(a.top+a.height/2,innerHeight-70)-29;const animation=image.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${dx}px,${dy}px) scale(.25)`,opacity:.2}],{duration:430,easing:'cubic-bezier(.3,.7,.3,1)'});animation.finished.finally(()=>image.remove());}
function addToCart(id,qty=1,from=null){const p=byId(id),existing=cart.find(i=>i.id===id);if(existing){if(existing.qty>=99){notify('Maksimal 99 paket per produk pada simulasi.');return;}existing.qty=Math.min(99,existing.qty+qty);}else cart.push({id,qty:Math.min(99,qty)});persistCart();flyToCart(p,from);$('#cartCount').classList.remove('bump');void $('#cartCount').offsetWidth;$('#cartCount').classList.add('bump');notify(`${p.name} ditambahkan ke keranjang.`);}
function renderCart(){if(!cart.length){$('#cartContents').innerHTML='<div class="cart-empty"><div class="empty-shapes" aria-hidden="true">○ △ □</div><h3>Masih ada ruang untuk ide baru.</h3><p>Jelajahi koleksi dan tambahkan<br>aktivitas yang menarik perhatian.</p><button class="button button-blue" data-close="cartDialog">Jelajahi koleksi →</button></div>';$('#cartSummary').hidden=true;return;}$('#cartSummary').hidden=false;$('#cartContents').innerHTML=cart.map(i=>{const p=byId(i.id);return `<div class="cart-row"><img src="assets/${p.image}.webp" alt="${p.name}" width="74" height="79"><div><div class="cart-row-name">${p.name}</div><div class="cart-row-price">${rupiah(p.price)} · harga contoh</div><div class="cart-row-controls"><div class="qty-control"><button data-cart-qty="${p.id}" data-delta="-1" aria-label="Kurangi jumlah ${p.name}">−</button><output aria-label="Jumlah ${p.name}">${i.qty}</output><button data-cart-qty="${p.id}" data-delta="1" aria-label="Tambah jumlah ${p.name}">+</button></div><button class="remove-item" data-remove="${p.id}" aria-label="Hapus ${p.name}">Hapus</button></div></div></div>`;}).join('');$('#cartSummary').innerHTML=`<div class="cart-subtotal"><span>Subtotal contoh</span><strong>${rupiah(subtotal())}</strong></div><p class="small-note">Ongkir menunggu konfirmasi. Keranjang ini merupakan simulasi dan belum dikirim ke TIGO LAB.</p><button class="button button-blue full-width" id="checkoutOpen">Coba checkout <span aria-hidden="true">→</span></button>`;}
$('#cartOpen').addEventListener('click',()=>{renderCart();openDialog('cartDialog');});
$('#cartContents').addEventListener('click',e=>{const qty=e.target.closest('[data-cart-qty]'),remove=e.target.closest('[data-remove]');if(qty){const item=cart.find(i=>i.id===qty.dataset.cartQty);if(!item)return;item.qty=Math.max(1,Math.min(99,item.qty+Number(qty.dataset.delta)));persistCart();renderCart();const replacement=$(`#cartContents button[data-cart-qty="${item.id}"][data-delta="${qty.dataset.delta}"]`);replacement?.focus({preventScroll:true});}if(remove){cart=cart.filter(i=>i.id!==remove.dataset.remove);persistCart();renderCart();notify('Produk dihapus dari keranjang.');}});
$('#cartSummary').addEventListener('click',e=>{if(!e.target.closest('#checkoutOpen')||!cart.length)return;closeDialog('cartDialog');$('#checkoutSummary').innerHTML=summaryHtml(cart);openDialog('checkoutDialog');});
function summaryHtml(items){return items.map(i=>{const p=byId(i.id);return `<div class="summary-item"><span>${p.name} × ${i.qty}</span><span>${rupiah(p.price*i.qty)}</span></div>`;}).join('')+`<div class="summary-line"><span>Subtotal produk contoh</span><strong>${rupiah(subtotal(items))}</strong></div><div class="shipping-line"><span>Ongkir</span><span>Menunggu konfirmasi</span></div>`;}
$('#checkoutForm').addEventListener('submit',e=>{e.preventDefault();if(!cart.length)return;const form=e.currentTarget;if(!form.reportValidity())return;const name=$('#demoName').value.trim(),city=$('#demoCity').value;if(name.length<2){$('#demoName').setCustomValidity('Gunakan nama contoh minimal dua karakter.');$('#demoName').reportValidity();return;}const savedItems=cart.map(i=>({id:i.id,qty:i.qty,name:byId(i.id).name,price:byId(i.id).price}));receipt={id:'DEMO-'+new Date().toISOString().slice(0,10).replace(/-/g,'')+'-'+crypto.getRandomValues(new Uint32Array(1))[0].toString(16).slice(0,5).toUpperCase(),name,city,items:savedItems,subtotal:subtotal(),createdAt:new Date().toISOString()};const saved=store.set('tigo-demo-receipt-v1',receipt);$('#demoReceipt').innerHTML=`<strong>${receipt.id}</strong><span>${safeText(name)} · ${safeText(city)}</span><div class="summary-line"><span>${savedItems.reduce((s,i)=>s+i.qty,0)} paket · subtotal contoh</span><strong>${rupiah(receipt.subtotal)}</strong></div><div class="shipping-line"><span>Ongkir</span><span>Menunggu konfirmasi</span></div>${saved?'':'<p class="small-note">Penyimpanan browser tidak tersedia. Unduh ringkasan sebelum menutup halaman.</p>'}`;cart=[];persistCart();closeDialog('checkoutDialog');openDialog('successDialog');form.reset();});
$('#demoName').addEventListener('input',e=>e.target.setCustomValidity(''));
$('#downloadReceipt').addEventListener('click',()=>{if(!receipt)return;const lines=['TIGO LAB — RINGKASAN SIMULASI','Ini bukan pesanan atau tagihan nyata.','',receipt.id,`Nama contoh: ${receipt.name}`,`Kota contoh: ${receipt.city}`,'',...receipt.items.map(i=>`${i.name} x ${i.qty} — ${rupiah(i.price*i.qty)} (harga contoh)`),'',`Subtotal contoh: ${rupiah(receipt.subtotal)}`,'Ongkir: menunggu konfirmasi','Total final: belum ditetapkan','','Ringkasan dibuat di browser; belum dikirim ke TIGO LAB.'];const blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`TIGO-LAB-${receipt.id}.txt`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
const featured=['M09',...products.filter(p=>p.id!=='M09').map(p=>p.id)];let heroSlide=0;
function setHero(delta){heroSlide=(heroSlide+delta+featured.length)%featured.length;const p=byId(featured[heroSlide]);const img=$('#heroImage');img.classList.remove('switching');img.src=`assets/${p.image}.webp`;img.alt=`${p.name}, gambar referensi produk Montessori TIGO LAB`;$('#heroProductName').textContent=p.name;$('#heroIndex').textContent=`PILIHAN ${p.id.slice(1)} / 10`;void img.offsetWidth;img.classList.add('switching');}
function openProductDemo(id){
  const product=byId(id),demo=productDemos[id];
  if(!product||!demo||$('#animationDialog').open)return;
  const video=$('#demoVideo');
  video.pause();
  $('#animationProductName').textContent=product.name;
  $('#animationTitle').textContent=demo.title;
  $('#animationDescription').textContent=demo.description;
  $('#animationNote').textContent=demo.note;
  $('#animationSteps').replaceChildren(...demo.steps.map(text=>{const item=document.createElement('li');item.textContent=text;return item;}));
  $('#animationError').hidden=true;
  $('#animationDownload').href=demo.video;
  $('#videoFallback').href=demo.video;
  video.setAttribute('aria-label',`Animasi cara bermain ${product.name}`);
  if(video.dataset.product!==id){
    video.poster=demo.poster;
    video.src=demo.video;
    video.dataset.product=id;
    video.load();
  }
  video.currentTime=0;
  openDialog('animationDialog');
  video.play().catch(()=>{/* Visitor can use native controls if playback needs another tap. */});
}
$('#animationDialog').addEventListener('close',()=>{$('#demoVideo').pause();});
$('#demoVideo').addEventListener('error',()=>{$('#animationError').hidden=false;});
document.addEventListener('visibilitychange',()=>{if(document.hidden)$('#demoVideo').pause();});
$('#heroPrev').addEventListener('click',()=>setHero(-1));$('#heroNext').addEventListener('click',()=>setHero(1));
$('#replayMotion').addEventListener('click',()=>openProductDemo(featured[heroSlide]));
renderProducts();updateBadge();
if('IntersectionObserver' in window&&!reduced()){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.remove('pending');entry.target.classList.add('in-view');observer.unobserve(entry.target);}}),{threshold:.08});$$('.reveal').forEach(el=>{if(el.getBoundingClientRect().top>innerHeight)el.classList.add('pending');observer.observe(el);});}
